set-variable.value:
@{
          var audit = new JObject {
            ["source"] = "upstream_model",
            ["inspectionState"] = "not_inspected",
            ["promptBlockReported"] = false,
            ["completionFilterReported"] = false,
            ["annotationErrors"] = 0,
            ["truncated"] = false,
            ["results"] = new JArray()
          };
          var contentType = context.Response.Headers.GetValueOrDefault("Content-Type", "").Split(';')[0].Trim().ToLowerInvariant();
          if (contentType == "text/event-stream") {
            audit["inspectionState"] = "stream_not_inspected";
            return JsonConvert.SerializeObject(audit);
          }
          if (contentType != "application/json" && !contentType.EndsWith("+json")) {
            audit["inspectionState"] = "non_json_not_inspected";
            return JsonConvert.SerializeObject(audit);
          }
          var encoding = context.Response.Headers.GetValueOrDefault("Content-Encoding", "");
          if (!string.IsNullOrEmpty(encoding) && !string.Equals(encoding, "identity", StringComparison.OrdinalIgnoreCase)) {
            audit["inspectionState"] = "encoded_body_not_inspected";
            return JsonConvert.SerializeObject(audit);
          }
          long declaredLength;
          if (long.TryParse(context.Response.Headers.GetValueOrDefault("Content-Length", ""), out declaredLength) && declaredLength > 262144) {
            audit["inspectionState"] = "oversize_not_inspected";
            return JsonConvert.SerializeObject(audit);
          }
          var body = context.Response.Body == null ? string.Empty : context.Response.Body.As<string>(preserveContent: true);
          if (body.Length > 131072) {
            audit["inspectionState"] = "oversize_not_inspected";
            return JsonConvert.SerializeObject(audit);
          }
          JToken parsed;
          try {
            parsed = JToken.Parse(body);
          }
          /* APIM exposes Exception, not JsonReaderException; only parser-library failures are handled. */
          catch (Exception parseError) {
            if (parseError.Source != "Newtonsoft.Json") { throw; }
            audit["inspectionState"] = "invalid_json";
            return JsonConvert.SerializeObject(audit);
          }
          var document = parsed as JObject;
          if (document == null) {
            audit["inspectionState"] = "unsupported_json_shape";
            return JsonConvert.SerializeObject(audit);
          }
          var error = (document["error"] as JObject) ?? document;
          var inner = (error?["innererror"] as JObject) ?? (error?["inner_error"] as JObject);
          var errorCode = error?["code"];
          var innerCode = inner?["code"];
          var code = errorCode?.Type == JTokenType.String ? (string)errorCode : string.Empty;
          audit["promptBlockReported"] = context.Response.StatusCode == 400
            && (code == "content_filter" || code == "content_policy_violation" || code == "ResponsibleAIPolicyViolation"
              || (innerCode?.Type == JTokenType.String && (string)innerCode == "ResponsibleAIPolicyViolation"));
          var errorFilters = inner?["content_filter_result"] ?? inner?["content_filter_results"]
            ?? error?["content_filter_result"] ?? error?["content_filter_results"];
          var prompts = document["prompt_filter_results"] ?? document["prompt_annotations"];
          var groups = new [] {
            prompts as JArray, document["choices"] as JArray,
            errorFilters == null ? null : new JArray(new JObject { ["content_filter_results"] = errorFilters })
          };
          var results = (JArray)audit["results"];
          var errors = 0;
          var truncated = false;
          if (prompts != null && !(prompts is JArray)) { errors++; }
          if (document["choices"] != null && !(document["choices"] is JArray)) { errors++; }
          for (var groupIndex = 0; groupIndex < groups.Length; groupIndex++) {
            var group = groups[groupIndex];
            if (group == null) { continue; }
            if (group.Count > 32) { truncated = true; }
            for (var itemIndex = 0; itemIndex < Math.Min(group.Count, 32); itemIndex++) {
              var item = group[itemIndex] as JObject;
              if (item == null) { errors++; continue; }
              var stage = groupIndex == 1 ? "completion" : "prompt";
              var finish = item["finish_reason"];
              if (groupIndex == 1 && finish?.Type == JTokenType.String && (string)finish == "content_filter") {
                audit["completionFilterReported"] = true;
              }
              var filters = item["content_filter_results"] as JObject;
              if (item["content_filter_results"] != null && filters == null) { errors++; }
              if (filters == null) { continue; }
              if (filters["error"] != null) { errors++; }
              var indexToken = item[groupIndex == 0 ? "prompt_index" : "index"];
              var index = -1;
              var validIndex = indexToken?.Type == JTokenType.Integer
                && int.TryParse(indexToken.ToString(), out index) && index >= 0 && index <= 999;
              if (!validIndex) { index = -1; }
              foreach (var category in new [] { "hate", "sexual", "violence", "self_harm", "jailbreak", "indirect_attack", "protected_material_text", "protected_material_code", "pii", "groundedness", "task_adherence" }) {
                var signal = filters[category] as JObject;
                if (filters[category] != null && signal == null) { errors++; }
                if (signal == null) { continue; }
                var severityToken = signal["severity"];
                var severity = severityToken?.Type == JTokenType.String ? (string)severityToken : string.Empty;
                var knownSeverity = severity == "safe" || severity == "low" || severity == "medium" || severity == "high";
                var filtered = signal["filtered"];
                var detected = signal["detected"];
                var redacted = signal["redacted"];
                if ((severityToken != null && severityToken.Type != JTokenType.Null && !knownSeverity)
                  || (filtered != null && filtered.Type != JTokenType.Null && filtered.Type != JTokenType.Boolean)
                  || (detected != null && detected.Type != JTokenType.Null && detected.Type != JTokenType.Boolean)
                  || (redacted != null && redacted.Type != JTokenType.Null && redacted.Type != JTokenType.Boolean)) { errors++; }
                if (!knownSeverity && filtered?.Type != JTokenType.Boolean
                  && detected?.Type != JTokenType.Boolean && redacted?.Type != JTokenType.Boolean) { continue; }
                if (results.Count >= 24) { truncated = true; continue; }
                results.Add(new JObject {
                  ["stage"] = stage, ["index"] = index, ["category"] = category,
                  ["severity"] = knownSeverity ? severity : null,
                  ["filtered"] = filtered?.Type == JTokenType.Boolean ? filtered : JValue.CreateNull(),
                  ["detected"] = detected?.Type == JTokenType.Boolean ? detected : JValue.CreateNull(),
                  ["redacted"] = redacted?.Type == JTokenType.Boolean ? redacted : JValue.CreateNull()
                });
              }
            }
          }
          audit["annotationErrors"] = errors;
          audit["truncated"] = truncated;
          var observed = results.Count > 0 || (bool)audit["promptBlockReported"] || (bool)audit["completionFilterReported"];
          audit["inspectionState"] = observed
            ? (errors > 0 || truncated ? "observed_partial" : "observed")
            : (errors > 0 ? "annotation_error" : "no_annotations");
          return JsonConvert.SerializeObject(audit);
        }
